<?php
/** RAG: why retrieval, chunking, embeddings and vector databases (pgvector), building the prompt, evaluation, hybrid search and reranking, ingestion and permissions, agentic RAG. */

if (!function_exists('fig_rag_pipeline')) {
    function fig_rag_pipeline(string $lane1, string $docs, string $chunks, string $vdb, string $lane2, string $q, string $search, string $prompt, string $llm): string
    {
        return <<<SVG
<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 640 330" font-family="system-ui, sans-serif" font-size="15" fill="#1E1C52"><defs><marker id="rg" viewBox="0 0 10 10" refX="9" refY="5" markerWidth="7" markerHeight="7" orient="auto-start-reverse"><path d="M0 0L10 5L0 10z" fill="#1E1C52"/></marker></defs><rect x="10" y="10" width="620" height="108" rx="14" fill="#F1F0F8"/><text x="24" y="32" font-size="13" font-weight="700" fill="#4A4775">{$lane1}</text><rect x="24" y="50" width="130" height="46" rx="10" fill="#FFFFFF" stroke="#8A87B0" stroke-width="2"/><text x="89.0" y="78.0" text-anchor="middle" font-size="13" font-weight="700" fill="#1E1C52">{$docs}</text><line x1="156" y1="73" x2="174" y2="73" stroke="#1E1C52" stroke-width="2" marker-end="url(#rg)"/><rect x="176" y="50" width="130" height="46" rx="10" fill="#DCEBFF" stroke="#2F8CF0" stroke-width="2"/><text x="241.0" y="78.0" text-anchor="middle" font-size="13" font-weight="700" fill="#1E1C52">{$chunks}</text><line x1="308" y1="73" x2="326" y2="73" stroke="#1E1C52" stroke-width="2" marker-end="url(#rg)"/><rect x="328" y="50" width="130" height="46" rx="10" fill="#ECE6FF" stroke="#7048E8" stroke-width="2"/><text x="393.0" y="78.0" text-anchor="middle" font-size="13" font-weight="700" fill="#1E1C52">embedding</text><line x1="460" y1="73" x2="478" y2="73" stroke="#1E1C52" stroke-width="2" marker-end="url(#rg)"/><rect x="480" y="50" width="130" height="46" rx="10" fill="#D5F6EA" stroke="#0B7F5C" stroke-width="2"/><text x="545.0" y="78.0" text-anchor="middle" font-size="13" font-weight="700" fill="#1E1C52">{$vdb}</text><rect x="10" y="132" width="620" height="188" rx="14" fill="#FFFFFF" stroke="#8A87B0" stroke-width="2"/><text x="24" y="154" font-size="13" font-weight="700" fill="#4A4775">{$lane2}</text><rect x="24" y="170" width="120" height="46" rx="10" fill="#F1F0F8" stroke="#8A87B0" stroke-width="2"/><text x="84.0" y="198.0" text-anchor="middle" font-size="13" font-weight="700" fill="#1E1C52">{$q}</text><rect x="176" y="170" width="120" height="46" rx="10" fill="#ECE6FF" stroke="#7048E8" stroke-width="2"/><text x="236.0" y="198.0" text-anchor="middle" font-size="13" font-weight="700" fill="#1E1C52">embedding</text><rect x="456" y="170" width="164" height="46" rx="10" fill="#D5F6EA" stroke="#0B7F5C" stroke-width="2"/><text x="538.0" y="198.0" text-anchor="middle" font-size="13" font-weight="700" fill="#1E1C52">{$search}</text><line x1="146" y1="193" x2="174" y2="193" stroke="#1E1C52" stroke-width="2" marker-end="url(#rg)"/><line x1="298" y1="193" x2="454" y2="193" stroke="#1E1C52" stroke-width="2" marker-end="url(#rg)"/><line x1="538" y1="98" x2="538" y2="168" stroke="#0B7F5C" stroke-width="2" stroke-dasharray="5 4" marker-end="url(#rg)"/><rect x="176" y="250" width="300" height="50" rx="10" fill="#FFE8D6" stroke="#E8590C" stroke-width="2"/><text x="326.0" y="280.0" text-anchor="middle" font-size="13" font-weight="700" fill="#B84508">{$prompt}</text><path d="M538 218 V275 H478" fill="none" stroke="#1E1C52" stroke-width="2" marker-end="url(#rg)"/><path d="M84 218 V275 H174" fill="none" stroke="#1E1C52" stroke-width="2" marker-end="url(#rg)"/><text x="301" y="314" text-anchor="middle" font-size="13" fill="#5E5B85">{$llm}</text></svg>
SVG;
    }
}

if (!function_exists('fig_rag_chunks')) {
    function fig_rag_chunks(string $doc, string $chunk, string $overlap, string $unit): string
    {
        return <<<SVG
<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 640 250" font-family="system-ui, sans-serif" font-size="15" fill="#1E1C52"><rect x="20" y="40" width="600" height="34" rx="8" fill="#F1F0F8" stroke="#8A87B0" stroke-width="2"/><text x="30" y="30" font-size="13" fill="#5E5B85">{$doc}</text><rect x="20" y="96" width="200" height="30" rx="8" fill="#DCEBFF" stroke="#2F8CF0" stroke-width="2"/><text x="120" y="116" text-anchor="middle" font-size="13" font-weight="700">{$chunk} 1 · 0–800</text><rect x="195" y="136" width="200" height="30" rx="8" fill="#ECE6FF" stroke="#7048E8" stroke-width="2"/><text x="295" y="156" text-anchor="middle" font-size="13" font-weight="700">{$chunk} 2 · 700–1500</text><rect x="370" y="176" width="200" height="30" rx="8" fill="#D5F6EA" stroke="#0B7F5C" stroke-width="2"/><text x="470" y="196" text-anchor="middle" font-size="13" font-weight="700">{$chunk} 3 · 1400–2200</text><rect x="195" y="40" width="25" height="34" fill="#FFE8D6" stroke="#E8590C" stroke-width="2"/><line x1="195" y1="76" x2="195" y2="220" stroke="#E8590C" stroke-width="1.5" stroke-dasharray="3 3"/><line x1="220" y1="76" x2="220" y2="220" stroke="#E8590C" stroke-width="1.5" stroke-dasharray="3 3"/><rect x="370" y="40" width="25" height="34" fill="#FFE8D6" stroke="#E8590C" stroke-width="2"/><line x1="370" y1="76" x2="370" y2="220" stroke="#E8590C" stroke-width="1.5" stroke-dasharray="3 3"/><line x1="395" y1="76" x2="395" y2="220" stroke="#E8590C" stroke-width="1.5" stroke-dasharray="3 3"/><text x="207.5" y="236" text-anchor="middle" font-size="13" fill="#B84508" font-weight="700">{$overlap}</text><text x="382.5" y="236" text-anchor="middle" font-size="13" fill="#B84508" font-weight="700">{$overlap}</text><text x="600" y="236" text-anchor="end" font-size="13" fill="#5E5B85">{$unit}</text></svg>
SVG;
    }
}

if (!function_exists('fig_rag_hybrid')) {
    function fig_rag_hybrid(string $vec, string $vecn, string $kw, string $kwn, string $cand, string $wide, string $fine, string $note): string
    {
        return <<<SVG
<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 640 270" font-family="system-ui, sans-serif" font-size="15" fill="#1E1C52"><defs><marker id="hy" viewBox="0 0 10 10" refX="9" refY="5" markerWidth="7" markerHeight="7" orient="auto-start-reverse"><path d="M0 0L10 5L0 10z" fill="#1E1C52"/></marker></defs><rect x="20" y="30" width="150" height="46" rx="10" fill="#ECE6FF" stroke="#7048E8" stroke-width="2"/><text x="95.0" y="58.0" text-anchor="middle" font-size="13" font-weight="700" fill="#5A35D0">{$vec}</text><rect x="20" y="150" width="150" height="46" rx="10" fill="#DCEBFF" stroke="#2F8CF0" stroke-width="2"/><text x="95.0" y="178.0" text-anchor="middle" font-size="13" font-weight="700" fill="#1B66BC">{$kw}</text><text x="95" y="98" text-anchor="middle" font-size="13">{$vecn}</text><text x="95" y="218" text-anchor="middle" font-size="13">{$kwn}</text><line x1="172" y1="53" x2="232" y2="110" stroke="#1E1C52" stroke-width="2" marker-end="url(#hy)"/><line x1="172" y1="173" x2="232" y2="128" stroke="#1E1C52" stroke-width="2" marker-end="url(#hy)"/><path d="M236 70 H376 L356 170 H256 Z" fill="#FFE8D6" stroke="#E8590C" stroke-width="2" stroke-linejoin="round"/><text x="306" y="112" text-anchor="middle" font-weight="700" fill="#B84508">RRF</text><text x="306" y="134" text-anchor="middle" font-size="13">50 {$cand}</text><line x1="378" y1="120" x2="418" y2="120" stroke="#1E1C52" stroke-width="2" marker-end="url(#hy)"/><path d="M416 84 H546 L526 156 H436 Z" fill="#D5F6EA" stroke="#0B7F5C" stroke-width="2" stroke-linejoin="round"/><text x="481" y="116" text-anchor="middle" font-size="13" font-weight="700" fill="#0B7F5C">reranker</text><text x="481" y="136" text-anchor="middle" font-size="13">cross-encoder</text><line x1="548" y1="120" x2="562" y2="120" stroke="#1E1C52" stroke-width="2" marker-end="url(#hy)"/><rect x="566" y="96" width="62" height="48" rx="10" fill="#FFFFFF" stroke="#0B7F5C" stroke-width="2"/><text x="597" y="125" text-anchor="middle" font-weight="700">top 5</text><text x="306" y="200" text-anchor="middle" font-size="13" fill="#5E5B85">{$wide}</text><text x="481" y="200" text-anchor="middle" font-size="13" fill="#5E5B85">{$fine}</text><text x="320" y="252" text-anchor="middle" font-size="13" fill="#5E5B85">{$note}</text></svg>
SVG;
    }
}

return [
    'id' => 'rag', 'family' => 'llm', 'after' => 'llm-api',
    'title' => L('RAG ed embedding', 'RAG and Embeddings'), 'short' => L('RAG', 'RAG'), 'level' => L('Avanzato', 'Advanced'),
    'desc' => L('Far rispondere un modello sui tuoi documenti: suddivisione in blocchi, embedding, database vettoriali con pgvector, costruzione del prompt, valutazione, ricerca ibrida e reranking, ingestione e permessi, RAG agentico.', 'Making a model answer from your documents: chunking, embeddings, vector databases with pgvector, building the prompt, evaluation, hybrid search and reranking, ingestion and permissions, agentic RAG.'),
    'lessons' => [
        lesson('why', L('Perché RAG', 'Why RAG'), [
            P('Un LLM non conosce i tuoi documenti interni né i fatti dopo la sua data di taglio. **RAG** (Retrieval-Augmented Generation) risolve così: alla domanda, si **cercano** i passaggi rilevanti nei tuoi documenti e li si mettono nel prompt; il modello risponde **basandosi su quelli**.', 'An LLM does not know your internal documents or facts after its cutoff. **RAG** (Retrieval-Augmented Generation) fixes it like this: on a question, you **retrieve** the relevant passages from your documents and put them in the prompt; the model answers **based on them**.'),
            C('domanda ──► cerca nei documenti ──► 5 passaggi rilevanti
                                         │
prompt = istruzioni + passaggi + domanda ──► LLM ──► risposta con citazioni', 'text'),
            P('Vantaggi: fatti aggiornati senza riaddestrare, risposte verificabili con le fonti, meno allucinazioni. Se i documenti sono pochi e brevi, a volte basta metterli tutti nel contesto, senza ricerca.', 'Advantages: up-to-date facts without retraining, answers verifiable through sources, fewer hallucinations. If the documents are few and short, sometimes you can put them all in the context, no search needed.'),
            Fig(L(fig_rag_pipeline('Indicizzazione: una volta, e a ogni documento nuovo', 'documenti', 'blocchi', 'database vettoriale', 'A ogni domanda', 'domanda', 'i 5 blocchi vicini', 'prompt: istruzioni + blocchi + domanda', 'poi l’LLM risponde citando le fonti'), fig_rag_pipeline('Indexing: once, and for every new document', 'documents', 'chunks', 'vector database', 'For every question', 'question', 'the 5 nearest chunks', 'prompt: instructions + chunks + question', 'then the LLM answers, citing the sources')),
                L('Due corsie. In alto l’indicizzazione: documenti, blocchi, embedding, database vettoriale. In basso, a ogni domanda: la domanda diventa un embedding, si cercano nel database i 5 blocchi più vicini e insieme alla domanda formano il prompt per l’LLM, che risponde citando le fonti.', 'Two lanes. At the top indexing: documents, chunks, embedding, vector database. At the bottom, for every question: the question becomes an embedding, the 5 closest chunks are searched in the database and together with the question they form the prompt for the LLM, which answers citing the sources.'),
                L('La parte lenta si fa una volta; a ogni domanda si cerca e si risponde.', 'The slow part is done once; for every question you search and answer.')),
        ], [
            Q('w1', L('Che cosa fa la “R” di RAG?', 'What does the “R” in RAG do?'), [L('Cerca i passaggi rilevanti', 'Retrieves the relevant passages'), L('Riaddestra il modello', 'Retrains the model'), L('Riavvia il server', 'Restarts the server'), L('Riduce il prompt', 'Reduces the prompt')], 0, L('Retrieval.', 'Retrieval.')),
            Q('w2', L('Qual è un vantaggio di RAG sul fine-tuning per i fatti?', 'What is an advantage of RAG over fine-tuning for facts?'), [L('Si aggiorna cambiando i documenti', 'It updates by changing documents'), L('Non serve nessun documento', 'No documents needed'), L('Costa sempre di più', 'It always costs more'), L('Rende il modello più grande', 'It makes the model bigger')], 0, L('Niente riaddestramento.', 'No retraining.')),
            Q('w3', L('Quando si può fare a meno della ricerca?', 'When can you skip retrieval?'), [L('Se i documenti stanno tutti nel contesto', 'If all documents fit in the context'), L('Mai', 'Never'), L('Se i documenti sono milioni', 'If there are millions of documents'), L('Se il modello è piccolo', 'If the model is small')], 0, L('La soluzione più semplice prima.', 'Simplest solution first.')),
        ], task('text', L('Metti in ordine i passi di RAG, uno per riga numerata da `1.` a `4.`: genera la risposta, cerca i passaggi, ricevi la domanda, costruisci il prompt.', 'Order the RAG steps, one per line numbered `1.` to `4.`: generate the answer, retrieve passages, receive the question, build the prompt.'), '', [re('^1\.\s*(ricevi|receive)', L('Prima la domanda', 'Question first')), re('^2\.\s*(cerca|retrieve)', L('Poi la ricerca', 'Then retrieval')), re('^3\.\s*(costruisci|build)', L('Poi il prompt', 'Then the prompt')), re('^4\.\s*(genera|generate)', L('Infine la risposta', 'Finally the answer'))], '', "1. ricevi la domanda\n2. cerca i passaggi\n3. costruisci il prompt\n4. genera la risposta"), [
            dMatch(pMatch(), [['Retrieval', L('Trovare i passaggi', 'Finding passages')], ['Augmented', L('Aggiungerli al prompt', 'Adding them to the prompt')], ['Generation', L('Scrivere la risposta', 'Writing the answer')], [L('Citazione', 'Citation'), L('Fonte verificabile', 'Verifiable source')]], L('Le tre lettere di RAG.', 'RAG’s three letters.')),
            dFlash(pFlash(), [[L('RAG riduce le allucinazioni', 'RAG reduces hallucinations'), true], [L('RAG richiede di riaddestrare il modello', 'RAG requires retraining the model'), false], [L('Con RAG si possono citare le fonti', 'With RAG you can cite sources'), true], [L('RAG funziona solo con documenti pubblici', 'RAG only works with public documents'), false]], L('Documenti giusti, risposte giuste.', 'Right documents, right answers.')),
        ]),
        lesson('chunking', L('Suddividere i documenti', 'Chunking documents'), [
            P('I documenti si dividono in **blocchi** (chunk) di qualche centinaio di token: abbastanza grandi da avere senso da soli, abbastanza piccoli da essere precisi. Una piccola **sovrapposizione** tra blocchi evita di spezzare un concetto a metà.', 'Documents are split into **chunks** of a few hundred tokens: big enough to make sense on their own, small enough to be precise. A small **overlap** between chunks avoids cutting a concept in half.'),
            P('La dimensione conta più di quanto sembri. Un blocco troppo grande mescola molti argomenti: il suo embedding diventa una media vaga e la ricerca lo trova male, e in più riempie il prompt di testo inutile. Un blocco troppo piccolo perde il contesto: «il termine è 30 giorni» non dice di quale termine si parla. Si parte di solito da 300–800 token con il 10–15% di sovrapposizione e si aggiusta misurando su domande vere.', 'Size matters more than it seems. A chunk that is too large mixes many topics: its embedding becomes a vague average that search finds poorly, and it also fills the prompt with useless text. A chunk that is too small loses context: “the deadline is 30 days” does not say which deadline. You usually start from 300–800 tokens with 10–15% overlap and adjust by measuring on real questions.'),
            Fig(L(fig_rag_chunks('Un documento di 2200 caratteri', 'blocco', 'sovrapposizione', 'dimensione 800, sovrapposizione 100'), fig_rag_chunks('A 2200-character document', 'chunk', 'overlap', 'size 800, overlap 100')),
                L('Una barra lunga rappresenta il documento. Sotto, tre blocchi di 800 caratteri: da 0 a 800, da 700 a 1500, da 1400 a 2200. Le due zone di 100 caratteri condivise tra blocchi vicini sono evidenziate in arancione.', 'A long bar stands for the document. Below, three 800-character chunks: from 0 to 800, from 700 to 1500, from 1400 to 2200. The two 100-character zones shared by neighbouring chunks are highlighted in orange.'),
                L('Ogni blocco ripete la coda del precedente: una frase tagliata compare intera almeno una volta.', 'Each chunk repeats the tail of the previous one: a cut sentence appears whole at least once.')),
            C('def blocchi(testo, dimensione=800, sovrapposizione=100):
    passo = dimensione - sovrapposizione
    return [testo[i:i + dimensione] for i in range(0, len(testo), passo)]

# meglio ancora: dividere per titoli e paragrafi, e salvare con ogni blocco
# i metadati: documento, sezione, pagina, data', 'python'),
            P('Dividere seguendo la struttura (titoli, paragrafi, articoli di un regolamento) funziona meglio che tagliare a caratteri. I **metadati** (titolo, pagina, data) servono per filtrare e per citare.', 'Splitting along the structure (headings, paragraphs, articles of a regulation) works better than cutting by characters. **Metadata** (title, page, date) help filter and cite.'),
        ], [
            Q('c1', L('Perché aggiungere sovrapposizione tra blocchi?', 'Why add overlap between chunks?'), [L('Per non spezzare un concetto a metà', 'To avoid cutting a concept in half'), L('Per occupare più spazio', 'To use more space'), L('Per confondere la ricerca', 'To confuse search'), L('Non serve', 'It is useless')], 0, L('Il contesto attraversa il taglio.', 'Context crosses the cut.')),
            Q('c2', L('Qual è il modo migliore di dividere un manuale?', 'What is the best way to split a manual?'), [L('Per titoli e paragrafi', 'By headings and paragraphs'), L('Ogni 10 caratteri', 'Every 10 characters'), L('A caso', 'At random'), L('Un blocco unico gigante', 'One giant chunk')], 0, L('Segui la struttura.', 'Follow the structure.')),
            Q('c3', L('A che cosa servono i metadati?', 'What is metadata for?'), [L('Filtrare e citare le fonti', 'Filtering and citing sources'), L('Colorare il testo', 'Colouring text'), L('Aumentare i token', 'Increasing tokens'), L('Niente', 'Nothing')], 0, L('Documento, pagina, data.', 'Document, page, date.')),
        ], task('python', L('Completa la funzione `blocchi`: con `passo = dimensione - sovrapposizione`, restituisci la lista `[testo[i:i + dimensione] for i in range(0, len(testo), passo)]`.', 'Complete the `blocchi` function: with `passo = dimensione - sovrapposizione`, return the list `[testo[i:i + dimensione] for i in range(0, len(testo), passo)]`.'), "def blocchi(testo, dimensione=800, sovrapposizione=100):\n    ", [re('passo\s*=\s*dimensione\s*-\s*sovrapposizione', L('Calcoli il passo', 'You compute the step')), re('return\s+\[\s*testo\s*\[\s*i\s*:\s*i\s*\+\s*dimensione\s*\]\s+for\s+i\s+in\s+range\s*\(\s*0\s*,\s*len\s*\(\s*testo\s*\)\s*,\s*passo\s*\)\s*\]', L('Restituisci i blocchi', 'You return the chunks'))], '', "passo = dimensione - sovrapposizione\n    return [testo[i:i + dimensione] for i in range(0, len(testo), passo)]"), [
            dMatch(pMatch(), [[L('Blocco', 'Chunk'), L('Pezzo di documento', 'Piece of document')], [L('Sovrapposizione', 'Overlap'), L('Testo condiviso tra blocchi', 'Text shared between chunks')], [L('Metadati', 'Metadata'), L('Titolo, pagina, data', 'Title, page, date')], [L('Struttura', 'Structure'), L('Titoli e paragrafi', 'Headings and paragraphs')]], L('Tagliare bene.', 'Cutting well.')),
            dFlash(pFlash(), [[L('Blocchi enormi rendono la ricerca meno precisa', 'Huge chunks make search less precise'), true], [L('Blocchi di 3 parole sono l’ideale', '3-word chunks are ideal'), false], [L('I metadati aiutano a citare', 'Metadata helps citing'), true], [L('Tagliare a caso è meglio che seguire i titoli', 'Cutting at random beats following headings'), false]], L('Il blocco giusto, al posto giusto.', 'The right chunk, in the right place.')),
        ]),
        lesson('vectors', L('Embedding e database vettoriali', 'Embeddings and vector databases'), [
            P('Ogni blocco viene trasformato in un **embedding** da un modello apposito e salvato in un **database vettoriale**. Alla domanda, si calcola il suo embedding e si cercano i blocchi più vicini (similarità del coseno). Se usi già PostgreSQL, l’estensione **pgvector** basta per iniziare.', 'Each chunk is turned into an **embedding** by a dedicated model and saved in a **vector database**. On a question, you compute its embedding and find the closest chunks (cosine similarity). If you already use PostgreSQL, the **pgvector** extension is enough to start.'),
            C('CREATE EXTENSION vector;
CREATE TABLE blocchi (
    id BIGSERIAL PRIMARY KEY,
    documento TEXT,
    testo TEXT,
    embedding vector(1024)
);
CREATE INDEX ON blocchi USING hnsw (embedding vector_cosine_ops);

-- i 5 blocchi più vicini alla domanda ($1 = embedding della domanda)
SELECT documento, testo FROM blocchi
ORDER BY embedding <=> $1
LIMIT 5;', 'sql'),
            P('`<=>` è la distanza del coseno (più piccola = più simile). L’indice **HNSW** rende veloce la ricerca anche su milioni di blocchi. Spesso si combina con la ricerca per parole chiave (**ricerca ibrida**), che trova nomi e codici esatti.', '`<=>` is cosine distance (smaller = more similar). The **HNSW** index makes search fast even over millions of chunks. It is often combined with keyword search (**hybrid search**), which finds exact names and codes.'),
        ], [
            Q('v1', L('Che cosa misura `<=>` in pgvector?', 'What does `<=>` measure in pgvector?'), [L('La distanza del coseno', 'Cosine distance'), L('L’uguaglianza esatta', 'Exact equality'), L('La lunghezza del testo', 'Text length'), L('La data', 'The date')], 0, L('Più piccola, più simile.', 'Smaller, more similar.')),
            Q('v2', L('A che cosa serve l’indice HNSW?', 'What is the HNSW index for?'), [L('Ricerca veloce dei vettori vicini', 'Fast nearest-vector search'), L('Ordinare per data', 'Sorting by date'), L('Cifrare i dati', 'Encrypting data'), L('Comprimere il testo', 'Compressing text')], 0, L('Approssimata ma rapidissima.', 'Approximate but very fast.')),
            Q('v3', L('Che cos’è la ricerca ibrida?', 'What is hybrid search?'), [L('Vettori più parole chiave', 'Vectors plus keywords'), L('Ricerca su due server', 'Search on two servers'), L('Ricerca a voce', 'Voice search'), L('Ricerca senza indice', 'Search without an index')], 0, L('Trova anche codici e nomi esatti.', 'It also finds exact codes and names.')),
        ], task('sql', L('Scrivi la query che restituisce `testo` dei 3 blocchi più vicini all’embedding `$1`, ordinando con `<=>`.', 'Write the query returning `testo` of the 3 chunks closest to embedding `$1`, ordering with `<=>`.'), '', [re('SELECT\s+testo\s+FROM\s+blocchi', L('Leggi i blocchi', 'You read the chunks')), re('ORDER\s+BY\s+embedding\s*<=>\s*\$1', L('Ordini per distanza', 'You order by distance')), re('LIMIT\s+3', L('Ne prendi 3', 'You take 3'))], '', "SELECT testo FROM blocchi ORDER BY embedding <=> \$1 LIMIT 3;"), [
            dBlanks(pFill(), "CREATE EXTENSION ___;\nCREATE TABLE doc (id SERIAL, testo TEXT, e ___(768));\nSELECT testo FROM doc ORDER BY e ___ $1 LIMIT 5;", ['vector', 'vector', '<=>'], ['pgai', 'array', '<>'], L('pgvector in tre righe.', 'pgvector in three lines.')),
            dOrder(pSort(), [L('Calcola l’embedding di ogni blocco', 'Compute each chunk’s embedding'), L('Salvalo nel database vettoriale', 'Store it in the vector database'), L('Calcola l’embedding della domanda', 'Compute the question’s embedding'), L('Cerca i blocchi più vicini', 'Find the closest chunks')], L('Indicizzare, poi cercare.', 'Index, then search.')),
        ]),
        lesson('prompt', L('Costruire il prompt', 'Building the prompt'), [
            P('I blocchi trovati vanno nel prompt in modo ordinato, ognuno con la sua fonte. Le istruzioni devono dire di rispondere **solo** in base ai documenti, di **citare** le fonti e di dire chiaramente quando la risposta non c’è.', 'The retrieved chunks go into the prompt in an orderly way, each with its source. The instructions must say to answer **only** from the documents, to **cite** the sources and to say clearly when the answer is not there.'),
            C('Rispondi alla domanda usando solo i documenti qui sotto.
Cita la fonte tra parentesi quadre, es. [regolamento.pdf, p. 4].
Se i documenti non contengono la risposta, scrivi: “Non trovo la risposta nei documenti.”

<documenti>
<doc fonte="regolamento.pdf, p. 4">Le ferie vanno richieste con 15 giorni di anticipo…</doc>
<doc fonte="faq.md">Le richieste si inviano dal portale HR…</doc>
</documenti>

Domanda: con quanto anticipo devo chiedere le ferie?', 'text'),
            P('Metti i documenti **prima** della domanda, separali con tag e non esagerare: troppi blocchi poco pertinenti confondono il modello e costano token.', 'Put the documents **before** the question, separate them with tags and do not overdo it: too many barely relevant chunks confuse the model and cost tokens.'),
        ], [
            Q('p1', L('Che cosa deve fare il modello se la risposta non è nei documenti?', 'What should the model do if the answer is not in the documents?'), [L('Dirlo chiaramente', 'Say so clearly'), L('Inventarla', 'Make it up'), L('Rispondere a un’altra domanda', 'Answer another question'), L('Non rispondere mai più', 'Never answer again')], 0, L('Meglio “non lo so” che un’invenzione.', 'Better “I don’t know” than a fabrication.')),
            Q('p2', L('Perché indicare la fonte di ogni blocco?', 'Why give each chunk’s source?'), [L('Per poter citare e verificare', 'To be able to cite and verify'), L('Per allungare il prompt', 'To lengthen the prompt'), L('Per il copyright del modello', 'For the model’s copyright'), L('Non serve', 'It is not needed')], 0, L('L’utente può controllare.', 'The user can check.')),
            Q('p3', L('Che cosa succede con troppi blocchi poco pertinenti?', 'What happens with too many barely relevant chunks?'), [L('Il modello si confonde e si spende di più', 'The model gets confused and costs rise'), L('La risposta migliora sempre', 'The answer always improves'), L('Niente', 'Nothing'), L('Il database si cancella', 'The database is deleted')], 0, L('Qualità prima della quantità.', 'Quality over quantity.')),
        ], task('text', L('Scrivi le istruzioni di un prompt RAG che: usa **solo** i documenti, **cita** la fonte e dice “Non trovo la risposta nei documenti” quando manca.', 'Write the instructions of a RAG prompt that: uses **only** the documents, **cites** the source and says “Non trovo la risposta nei documenti” when it is missing.'), '', [re('solo|only', L('Solo i documenti', 'Only the documents')), re('cit|fonte|source', L('Chiedi le citazioni', 'You ask for citations')), re('Non trovo la risposta nei documenti', L('Gestisci la risposta mancante', 'You handle the missing answer'))], '', 'Rispondi usando solo i documenti forniti e cita la fonte tra parentesi quadre. Se i documenti non contengono la risposta, scrivi: “Non trovo la risposta nei documenti.”'), [
            dOrder(pSort(), [L('Istruzioni', 'Instructions'), L('<documenti> con le fonti', '<documents> with sources'), L('Domanda dell’utente', 'User question')], L('L’ordine del prompt RAG.', 'The RAG prompt order.')),
            dFlash(pFlash(), [[L('Conviene mettere i documenti prima della domanda', 'Documents should come before the question'), true], [L('Più blocchi sono sempre meglio', 'More chunks are always better'), false], [L('Il modello deve poter dire che la risposta manca', 'The model must be able to say the answer is missing'), true], [L('Le fonti si possono omettere', 'Sources can be omitted'), false]], L('Un buon prompt RAG.', 'A good RAG prompt.')),
        ]),
        lesson('evaluate', L('Valutare e migliorare', 'Evaluating and improving'), [
            P('Un sistema RAG può sbagliare in due punti: la **ricerca** (non trova il blocco giusto) o la **generazione** (lo trova ma risponde male). Si valutano separatamente: per la ricerca, il blocco giusto è tra i primi *k*? Per la risposta, è **fedele** ai documenti e **pertinente** alla domanda?', 'A RAG system can fail at two points: **retrieval** (it does not find the right chunk) or **generation** (it finds it but answers badly). Evaluate them separately: for retrieval, is the right chunk in the top *k*? For the answer, is it **faithful** to the documents and **relevant** to the question?'),
            P('Miglioramenti tipici: un **reranker** che riordina i risultati con un modello più preciso, la ricerca ibrida, riscrivere la domanda prima di cercare, filtri sui metadati (reparto, data), blocchi migliori. Cambia una cosa alla volta e misura con lo stesso insieme di domande.', 'Typical improvements: a **reranker** reordering results with a more precise model, hybrid search, rewriting the question before searching, metadata filters (department, date), better chunks. Change one thing at a time and measure with the same set of questions.'),
            C('domanda                                  blocco atteso        trovato nei primi 5?
“Anticipo per le ferie?”                 regolamento p.4      ✓
“Rimborso km auto propria?”              rimborsi.pdf p.2     ✗ → aggiungi ricerca ibrida', 'text'),
        ], [
            Q('e1', L('Quali sono i due punti di errore di RAG?', 'What are RAG’s two failure points?'), [L('Ricerca e generazione', 'Retrieval and generation'), L('Tastiera e mouse', 'Keyboard and mouse'), L('Server e client', 'Server and client'), L('Token e byte', 'Tokens and bytes')], 0, L('Vanno valutati separatamente.', 'They must be evaluated separately.')),
            Q('e2', L('Che cosa fa un reranker?', 'What does a reranker do?'), [L('Riordina i risultati con un modello più preciso', 'Reorders results with a more precise model'), L('Cancella i documenti', 'Deletes documents'), L('Traduce la domanda', 'Translates the question'), L('Aumenta i blocchi', 'Increases chunks')], 0, L('Prima ampio, poi preciso.', 'Broad first, then precise.')),
            Q('e3', L('Che cosa significa risposta “fedele”?', 'What does a “faithful” answer mean?'), [L('Basata solo sui documenti', 'Based only on the documents'), L('Molto lunga', 'Very long'), L('Scritta in rima', 'Written in rhyme'), L('Data velocemente', 'Given quickly')], 0, L('Niente aggiunte inventate.', 'No invented additions.')),
        ], task('text', L('Proponi due miglioramenti per un RAG che non trova i codici prodotto esatti, uno per riga che inizia con `-`.', 'Suggest two improvements for a RAG that cannot find exact product codes, one per line starting with `-`.'), "- \n- ", [re('^-\s*\S.{5,}\n-\s*\S.{5,}', L('Due proposte', 'Two proposals')), re('ibrid|hybrid|parole chiave|keyword|BM25|full.?text', L('Una riguarda la ricerca per parole chiave', 'One is about keyword search'))], '', "- aggiungere la ricerca ibrida con parole chiave\n- filtrare per metadati come categoria del prodotto"), [
            dMatch(pMatch(), [['Reranker', L('Riordina i risultati', 'Reorders results')], [L('Ricerca ibrida', 'Hybrid search'), L('Vettori + parole chiave', 'Vectors + keywords')], [L('Fedeltà', 'Faithfulness'), L('Risposta basata sui documenti', 'Answer grounded in documents')], [L('Top-k', 'Top-k'), L('Il blocco giusto è tra i primi', 'The right chunk is near the top')]], L('Misurare un RAG.', 'Measuring a RAG.')),
            dFlash(pFlash(), [[L('Ricerca e generazione vanno valutate separatamente', 'Retrieval and generation must be evaluated separately'), true], [L('Conviene cambiare tutto insieme', 'Better change everything at once'), false], [L('I filtri sui metadati possono aiutare', 'Metadata filters can help'), true], [L('Se la ricerca sbaglia, la risposta sarà comunque giusta', 'If retrieval fails, the answer will still be right'), false]], L('Un pezzo alla volta.', 'One piece at a time.')),
        ]),
        lesson('hybrid', L('Ricerca ibrida e reranking', 'Hybrid search and reranking'), [
            P('La ricerca vettoriale capisce il significato ma sbaglia su codici, sigle e nomi esatti; la ricerca per **parole chiave** (BM25, full-text) fa l’opposto. La **ricerca ibrida** le esegue entrambe e unisce le due classifiche. Un metodo semplice e robusto è la **Reciprocal Rank Fusion** (RRF): ogni documento prende punti in base alla sua posizione in ciascuna classifica.', 'Vector search understands meaning but fails on codes, acronyms and exact names; **keyword** search (BM25, full-text) does the opposite. **Hybrid search** runs both and merges the two rankings. A simple, robust method is **Reciprocal Rank Fusion** (RRF): each document scores points based on its position in each ranking.'),
            C('def rrf(*classifiche, k=60):
    punteggi = {}
    for classifica in classifiche:
        for posizione, doc in enumerate(classifica):
            punteggi[doc] = punteggi.get(doc, 0) + 1 / (k + posizione + 1)
    return sorted(punteggi, key=punteggi.get, reverse=True)

migliori = rrf(risultati_vettoriali, risultati_parole_chiave)[:50]', 'python'),
            P('Poi un **reranker** (un modello *cross-encoder*) legge insieme la domanda e ciascuno dei 50 candidati e dà un punteggio di pertinenza molto più preciso; si tengono i primi 5. È lento per milioni di documenti, ma perfetto su poche decine: prima si cerca **largo**, poi si ordina **fine**.', 'Then a **reranker** (a *cross-encoder* model) reads the question together with each of the 50 candidates and gives a much more precise relevance score; you keep the top 5. It is slow over millions of documents, but perfect on a few dozen: first search **wide**, then sort **fine**.'),
            Fig(L(fig_rag_hybrid('ricerca vettoriale', 'capisce il significato', 'parole chiave', 'trova codici e nomi', 'candidati', 'cerca largo', 'ordina fine', 'Due classifiche unite, poi un modello più lento rilegge solo i migliori.'), fig_rag_hybrid('vector search', 'understands meaning', 'keywords', 'finds codes and names', 'candidates', 'search wide', 'sort fine', 'Two rankings merged, then a slower model rereads only the best.')),
                L('Due riquadri a sinistra, ricerca vettoriale e ricerca per parole chiave, confluiscono in un imbuto arancione RRF che dà 50 candidati; un secondo imbuto verde, il reranker cross-encoder, li riduce ai migliori 5.', 'Two boxes on the left, vector search and keyword search, flow into an orange RRF funnel giving 50 candidates; a second green funnel, the cross-encoder reranker, narrows them to the top 5.'),
                L('Prima la quantità, poi la precisione.', 'Quantity first, then precision.')),
        ], [
            Q('h1', L('In che cosa è più forte la ricerca per parole chiave?', 'What is keyword search better at?'), [L('Capire sinonimi e parafrasi', 'Understanding synonyms and paraphrases'), L('Tradurre la domanda in altre lingue', 'Translating the question into other languages'), L('Riassumere i documenti trovati', 'Summarising the documents found'), L('Trovare codici, sigle e nomi esatti', 'Finding exact codes, acronyms and names')], 3, L('I vettori capiscono il senso, le parole chiave la lettera.', 'Vectors grasp the sense, keywords the letter.')),
            Q('h2', L('Come assegna i punti la Reciprocal Rank Fusion?', 'How does Reciprocal Rank Fusion assign points?'), [L('In base alla posizione in ciascuna classifica', 'Based on position in each ranking'), L('In base alla lunghezza del documento', 'Based on document length'), L('In base alla data del documento', 'Based on document date'), L('A caso, poi si fa la media', 'At random, then averaged')], 0, L('1 / (k + posizione).', '1 / (k + position).')),
            Q('h3', L('Perché il reranker si usa solo sui primi candidati?', 'Why is the reranker used only on the top candidates?'), [L('Perché funziona solo con 5 documenti', 'Because it only works with 5 documents'), L('È preciso ma lento: su milioni di documenti costerebbe troppo', 'It is precise but slow: over millions of documents it would cost too much'), L('Perché ignora la domanda dell’utente', 'Because it ignores the user’s question'), L('Perché i primi sono sempre già giusti', 'Because the top ones are always already right')], 1, L('Largo prima, fine dopo.', 'Wide first, fine after.')),
        ], task('python', L('Completa `rrf`: dentro il doppio ciclo aggiungi a `punteggi[doc]` il valore `1 / (k + posizione + 1)`.', 'Complete `rrf`: inside the double loop add to `punteggi[doc]` the value `1 / (k + posizione + 1)`.'), "def rrf(*classifiche, k=60):\n    punteggi = {}\n    for classifica in classifiche:\n        for posizione, doc in enumerate(classifica):\n            pass\n    return sorted(punteggi, key=punteggi.get, reverse=True)", [re('punteggi\s*\[\s*doc\s*\]\s*=\s*punteggi\.get\s*\(\s*doc\s*,\s*0\s*\)\s*\+\s*1\s*/\s*\(\s*k\s*\+\s*posizione\s*\+\s*1\s*\)|punteggi\s*\[\s*doc\s*\]\s*\+=\s*1\s*/\s*\(\s*k\s*\+\s*posizione\s*\+\s*1\s*\)', L('Il punteggio RRF', 'The RRF score'))], '', "def rrf(*classifiche, k=60):\n    punteggi = {}\n    for classifica in classifiche:\n        for posizione, doc in enumerate(classifica):\n            punteggi[doc] = punteggi.get(doc, 0) + 1 / (k + posizione + 1)\n    return sorted(punteggi, key=punteggi.get, reverse=True)"), [
            dOrder(pSort(), [L('Ricerca vettoriale', 'Vector search'), L('Ricerca per parole chiave', 'Keyword search'), L('Fusione delle classifiche (RRF)', 'Ranking fusion (RRF)'), L('Reranking dei primi 50', 'Reranking the top 50'), L('I primi 5 nel prompt', 'The top 5 into the prompt')], L('Una pipeline di ricerca moderna.', 'A modern retrieval pipeline.')),
            dMatch(pMatch(), [['BM25', L('Ricerca per parole chiave', 'Keyword search')], [L('Embedding', 'Embeddings'), L('Ricerca per significato', 'Search by meaning')], ['RRF', L('Unisce le classifiche', 'Merges rankings')], ['Reranker', L('Riordina con precisione', 'Reorders precisely')]], L('Il meglio dei due mondi.', 'The best of both worlds.')),
        ]),
        lesson('ingest', L('Ingestione, aggiornamenti e permessi', 'Ingestion, updates and permissions'), [
            P('La qualità di un RAG si decide all’**ingestione**. I PDF nascondono tabelle, colonne e scansioni (che richiedono l’OCR); conviene estrarre il testo con uno strumento adatto e controllarne un campione. Un trucco utile: prima di calcolare l’embedding, aggiungi a ogni blocco un breve **contesto** (titolo del documento, sezione), così un blocco come “il termine è di 30 giorni” non resta ambiguo.', 'A RAG’s quality is decided at **ingestion**. PDFs hide tables, columns and scans (which need OCR); extract the text with a suitable tool and check a sample. A useful trick: before computing the embedding, add a short **context** to each chunk (document title, section), so a chunk like “the deadline is 30 days” is not left ambiguous.'),
            C('-- solo blocchi di documenti che l’utente può vedere, e non scaduti
SELECT documento, testo FROM blocchi
WHERE reparto = ANY($2)            -- $2 = reparti dell’utente
  AND (valido_fino IS NULL OR valido_fino > now())
ORDER BY embedding <=> $1
LIMIT 5;', 'sql'),
            P('I documenti cambiano: quando uno viene aggiornato, **cancella** i suoi vecchi blocchi e ricrea i nuovi (un hash del contenuto dice se è cambiato davvero). E i **permessi** si applicano nella ricerca, con un filtro come quello qui sopra: non chiedere mai al modello di “non mostrare” documenti riservati, perché un’istruzione nel prompt non è una protezione.', 'Documents change: when one is updated, **delete** its old chunks and create the new ones (a content hash tells whether it really changed). And **permissions** are applied in the search, with a filter like the one above: never ask the model to “not show” confidential documents, because an instruction in the prompt is not protection.'),
        ], [
            Q('n1', L('Perché aggiungere titolo e sezione a ogni blocco prima dell’embedding?', 'Why add title and section to each chunk before the embedding?'), [L('Per rendere i blocchi più corti', 'To make chunks shorter'), L('Per nascondere i blocchi agli utenti', 'To hide chunks from users'), L('Perché il database lo richiede', 'Because the database requires it'), L('Così il blocco non resta ambiguo fuori dal documento', 'So the chunk is not ambiguous outside the document')], 3, L('Il contesto viaggia con il blocco.', 'The context travels with the chunk.')),
            Q('n2', L('Come si impedisce a un utente di ricevere documenti riservati?', 'How do you stop a user from getting confidential documents?'), [L('Filtrando per permessi nella query di ricerca', 'Filtering by permissions in the search query'), L('Scrivendo nel prompt di non mostrarli', 'Writing in the prompt not to show them'), L('Usando un modello più grande', 'Using a bigger model'), L('Mettendo i documenti in fondo al prompt', 'Putting the documents at the end of the prompt')], 0, L('Il prompt non è una barriera di sicurezza.', 'The prompt is not a security barrier.')),
            Q('n3', L('Un documento viene aggiornato. Che cosa fai con i suoi blocchi?', 'A document is updated. What do you do with its chunks?'), [L('Aggiungi i nuovi e lasci anche i vecchi', 'Add the new ones and keep the old ones too'), L('Cancelli i vecchi blocchi e crei i nuovi', 'Delete the old chunks and create the new ones'), L('Non serve fare nulla', 'Nothing needs doing'), L('Riaddestri il modello linguistico', 'Retrain the language model')], 1, L('Niente risposte da versioni superate.', 'No answers from outdated versions.')),
        ], task('sql', L('Aggiungi alla query un filtro `WHERE reparto = ANY($2)` così che si cerchi solo tra i documenti dei reparti dell’utente.', 'Add to the query a filter `WHERE reparto = ANY($2)` so it only searches the documents of the user’s departments.'), "SELECT testo FROM blocchi\nORDER BY embedding <=> \$1\nLIMIT 5;", [re('WHERE\s+reparto\s*=\s*ANY\s*\(\s*\$2\s*\)', L('Il filtro sui permessi', 'The permission filter')), re('WHERE[\s\S]*ORDER\s+BY\s+embedding\s*<=>\s*\$1', L('Il filtro viene prima dell’ordinamento', 'The filter comes before the ordering'))], '', "SELECT testo FROM blocchi\nWHERE reparto = ANY(\$2)\nORDER BY embedding <=> \$1\nLIMIT 5;"), [
            dBug(pBug(), ['istruzioni = "Rispondi solo dai documenti."', 'istruzioni += " Non mostrare i documenti riservati."', 'blocchi = cerca(domanda, filtro={"reparto": reparti_utente})', 'risposta = modello(istruzioni, blocchi, domanda)'], 1, '# i riservati sono già esclusi dal filtro nella ricerca', L('Un’istruzione nel prompt non protegge: il filtro nella ricerca sì.', 'A prompt instruction does not protect: the search filter does.')),
            dFlash(pFlash(), [[L('I PDF scansionati richiedono l’OCR', 'Scanned PDFs need OCR'), true], [L('Chiedere al modello di non mostrare un documento basta a proteggerlo', 'Asking the model not to show a document is enough to protect it'), false], [L('Un hash del contenuto aiuta a capire se un documento è cambiato', 'A content hash helps tell whether a document changed'), true], [L('I blocchi vecchi vanno sempre tenuti', 'Old chunks should always be kept'), false]], L('Dati puliti, accessi giusti.', 'Clean data, correct access.')),
        ]),
        lesson('agentic', L('RAG agentico', 'Agentic RAG'), [
            P('Nel RAG classico si cerca **una volta** con la domanda così com’è. Nel **RAG agentico** la ricerca diventa uno **strumento** che il modello usa quando vuole: può riformulare la domanda, cercare più volte, combinare risultati di fonti diverse e fermarsi quando ha abbastanza prove. Serve per domande in più passi (“quale fornitore ha il contratto più lungo e chi lo ha firmato?”).', 'In classic RAG you search **once** with the question as it is. In **agentic RAG** search becomes a **tool** the model uses when it wants: it can rephrase the question, search several times, combine results from different sources and stop when it has enough evidence. It helps with multi-step questions (“which supplier has the longest contract and who signed it?”).'),
            C('{
  "name": "cerca_documenti",
  "description": "Cerca nei documenti aziendali. Usalo con parole chiave precise; puoi chiamarlo più volte con domande diverse. Restituisce fino a 5 blocchi con fonte e pagina.",
  "input_schema": {
    "type": "object",
    "properties": {
      "query": {"type": "string"},
      "anno": {"type": "integer", "description": "Filtra per anno del documento"}
    },
    "required": ["query"]
  }
}', 'json'),
            P('Il prezzo: più chiamate, più latenza e più costo, e il rischio che il modello cerchi all’infinito. Metti un **limite** di ricerche, chiedi di citare le fonti e valuta con gli stessi casi di test del RAG classico per capire se il guadagno di qualità vale la spesa.', 'The price: more calls, more latency and more cost, and the risk the model searches forever. Set a **limit** on searches, ask it to cite sources and evaluate with the same test cases as classic RAG to see whether the quality gain is worth the cost.'),
        ], [
            Q('g1', L('Che cosa cambia nel RAG agentico rispetto a quello classico?', 'What changes in agentic RAG compared with classic RAG?'), [L('Non si usano più i documenti', 'Documents are no longer used'), L('Il modello viene riaddestrato sui documenti', 'The model is retrained on the documents'), L('La ricerca è uno strumento che il modello usa quando e quanto serve', 'Search is a tool the model uses when and as much as needed'), L('Si cerca sempre una sola volta', 'You always search just once')], 2, L('Il modello guida la ricerca.', 'The model drives the search.')),
            Q('g2', L('Per quale domanda serve di più il RAG agentico?', 'For which question does agentic RAG help most?'), [L('Una domanda in più passi che unisce più documenti', 'A multi-step question joining several documents'), L('“Che ore sono?”', '“What time is it?”'), L('Una domanda la cui risposta sta in un solo blocco', 'A question answered by a single chunk'), L('Un saluto dell’utente', 'A greeting from the user')], 0, L('Cerca, legge, cerca ancora.', 'It searches, reads, searches again.')),
            Q('g3', L('Quale rischio va limitato nel RAG agentico?', 'Which risk must be limited in agentic RAG?'), [L('Che il modello smetta di usare i documenti', 'That the model stops using documents'), L('Che il modello cerchi all’infinito, con costi alti', 'That the model searches forever, at high cost'), L('Che i documenti vengano cancellati', 'That documents get deleted'), L('Che le citazioni siano troppo precise', 'That citations are too precise')], 1, L('Serve un limite di ricerche.', 'A search limit is needed.')),
        ], task('json', L('Scrivi lo strumento `cerca_normativa` con una descrizione di almeno 40 caratteri e un `input_schema` con `query` (string) obbligatoria.', 'Write the tool `cerca_normativa` with a description of at least 40 characters and an `input_schema` with a required `query` (string).'), '', [re('"name"\s*:\s*"cerca_normativa"', L('Il nome', 'The name')), re('"description"\s*:\s*"[^"]{40,}"', L('Una descrizione utile', 'A useful description')), re('"query"\s*:\s*\{\s*"type"\s*:\s*"string"', L('Il campo query', 'The query field')), re('"required"\s*:\s*\[[^\]]*"query"', L('Query obbligatoria', 'Query required'))], '', "{\n  \"name\": \"cerca_normativa\",\n  \"description\": \"Cerca nelle leggi e nei regolamenti interni. Usalo con parole chiave precise, anche più volte.\",\n  \"input_schema\": {\n    \"type\": \"object\",\n    \"properties\": {\"query\": {\"type\": \"string\"}},\n    \"required\": [\"query\"]\n  }\n}"), [
            dOrder(pSort(), [L('Il modello riformula la domanda', 'The model rephrases the question'), L('Chiama lo strumento di ricerca', 'It calls the search tool'), L('Legge i risultati', 'It reads the results'), L('Se mancano prove cerca ancora', 'If evidence is missing it searches again'), L('Risponde citando le fonti', 'It answers citing sources')], L('Cercare come un ricercatore.', 'Searching like a researcher.')),
            dFlash(pFlash(), [[L('Nel RAG agentico la ricerca è uno strumento', 'In agentic RAG search is a tool'), true], [L('Il RAG agentico costa sempre meno del classico', 'Agentic RAG always costs less than classic'), false], [L('Conviene limitare il numero di ricerche', 'It pays to limit the number of searches'), true], [L('Il RAG agentico non ha bisogno di valutazione', 'Agentic RAG needs no evaluation'), false]], L('Più autonomia, più controlli.', 'More autonomy, more checks.')),
        ]),
